/**
 * Ends the session in order: its applications are asked to exit and get a grace period
 * before the session is terminated. Returns once the session is closed. Closing a closed
 * session succeeds.
 *
 * The owner may close their own session; closing another member's requires
 * `fleet:sessions.manage`. Fails with `MACHINE_OFFLINE` or `MACHINE_TIMEOUT` as
 * for opening a session.
 * @summary Close a session
 */
export const closeSession = async (
  sessionId: string,
  options?: RequestInit,
  fetchFn?: typeof globalThis.fetch,
): Promise<closeSessionResponse> => {
  const res = await (fetchFn ?? fetch)(getCloseSessionUrl(sessionId), {
    ...options,
    method: "POST",
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: closeSessionResponse["data"] = body ? JSON.parse(body) : {};
  return { data, status: res.status, headers: res.headers } as closeSessionResponse;
};

